// ZOEKKERN v2 — SYNONIEMEN uk/ru/nl/en/de/fr/pl/ro/bg (Z1, 22.10.2026). Elke groep is één begrip over de domeinen van de
// site (post, bestanden, agenda, instellingen, taal, thema, beveiliging, passkey, sessies, AI/agenten/connector, apparaten,
// bord, GitHub, cloud/Drive, meldingen, account, afmelden, hulp, algemene handelingen, dagelijkse begrippen). De leden gaan
// door zoekNorm(), dus Cyrillische leden vallen samen met hun transliteratie. Uitbreiding van een zoekvraag geeft per token
// een OF-groep (token | varianten | synoniemen); tussen de tokens blijft EN (met dekking, zie zoek-rangschikking.ts).
//
// Uitbreidbaar: (1) hier een groep toevoegen (bron 'ingebouwd'); (2) per lade in app.zoek_synoniemen_eigenaar
// (bron 'eigenaar', backend/zoek-index.ts → eigenSynoniemen), meegegeven als `extra` aan synoniemen()/breidUit().
// Identificatoren, bestandsnamen en productnamen worden NIET vertaald (geen groep voor «GitHub», «Google», «Drive»-als-merk).
import { zoekNorm } from './zoek-normalisatie';
import type { ZoekSynoniemGroep, ZoekTaal } from './zoek-model';

type Leden = Partial<Record<ZoekTaal, readonly string[]>>;
const g = (canoniek: string, domein: string, leden: Leden): ZoekSynoniemGroep => ({
  canoniek, taal: 'multi', domein, bron: 'ingebouwd',
  synoniemen: [...new Set(Object.values(leden).flat().map(w => String(w)))],
});

