// ------------------------------------------------------------------------------------------------ index en opzoeken
let index: Map<string, Set<string>> | null = null;
const normLid = (w: string) => zoekNorm(w).replace(/[^\p{L}\p{N} ]+/gu, ' ').replace(/\s+/g, ' ').trim();
function indexVan(groepen: ReadonlyArray<ZoekSynoniemGroep>, m = new Map<string, Set<string>>()): Map<string, Set<string>> {
  for (const groep of groepen) {
    // Meerwoordige leden tellen mee als geheel (voor zinsuitbreiding) én elk woord ≥ 3 van zo'n lid NIET los (anders
    // zou «mail» via «e-mail instellingen» aan «instellingen» kleven).
    const leden = new Set(groep.synoniemen.map(normLid).filter(w => w.length >= 2));
    for (const w of leden) { const al = m.get(w) || new Set<string>(); for (const x of leden) al.add(x); m.set(w, al); }
  }
  return m;
}
function bouw(): Map<string, Set<string>> { return indexVan(SYNONIEM_GROEPEN); }

/**
 * Synoniemen van één genormaliseerd token (het token zelf eerst), max 80 (een woord kan in twee groepen zitten). `extra` = groepen van de eigenaar (per lade,
 * backend/zoek-index.ts → eigenSynoniemen). Meerwoordige synoniemen worden teruggegeven als 'a b' (de kern maakt er een
 * tsquery-zin van).
 */
export function synoniemen(token: string, extra: ReadonlyArray<ZoekSynoniemGroep> = []): string[] {
  index ??= bouw();
  const eigen = extra.length ? indexVan(extra) : null;
  const uit = new Set<string>([token]);
  for (const w of index.get(token) || []) uit.add(w);
  for (const w of eigen?.get(token) || []) uit.add(w);
  return [...uit].slice(0, 80);
}

/** Zoekvraag-uitbreiding: per token een OF-groep. */
export const breidUit = (tokens: readonly string[], extra: ReadonlyArray<ZoekSynoniemGroep> = []): string[][] => tokens.map(t => synoniemen(t, extra));

let bekend: Set<string> | null = null;
/** Is dit genormaliseerde woord een lid van het ingebouwde woordenboek (of van `extra`)? Gecachet: O(1) per woord. */
export function isBekendSynoniem(token: string, extra: ReadonlyArray<ZoekSynoniemGroep> = []): boolean {
  bekend ??= new Set(SYNONIEM_GROEPEN.flatMap(g => g.synoniemen.map(normLid)));
  return bekend.has(token) || extra.some(g => g.synoniemen.some(w => normLid(w) === token));
}
/** De groep waar een genormaliseerd woord in zit (voor «waarom relevant»: synoniem/vertaling). null = geen groep. */
export function groepVan(token: string, extra: ReadonlyArray<ZoekSynoniemGroep> = []): ZoekSynoniemGroep | null {
  for (const groep of [...extra, ...SYNONIEM_GROEPEN]) if (groep.synoniemen.some(w => normLid(w) === token)) return groep;
  return null;
}

/** Aantal ingebouwde groepen (de test eist ≥ 120) en de talen die elke groep dekt. */
export const SYNONIEM_STATISTIEK = () => ({ groepen: SYNONIEM_GROEPEN.length, leden: SYNONIEM_GROEPEN.reduce((s, g) => s + g.synoniemen.length, 0) });
